head.script:
scwin.screenId = "jldstf30661";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_beforeName", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("beforeName"))); } },
        { childId: "ipt_comCode", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("comCode"))); } },
        { childId: "ipt_comName", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("comName"))); } },
        { childId: "cal_strDate", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("strDate"))); } },
        { childId: "cal_endDate", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("endDate"))); } },
        { childId: "ipt_stockRate1", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("stockRate1"))); } },
        { childId: "ipt_stockRate2", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("stockRate2"))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init = function () {
    /* sdd-asis-lifecycle:begin init — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ('null' === 'end') {

    }
    const f = (document.form || { elements: [] });
    if ('null' === '' && 'null' === '') {
        setPeriod('12');
    }
    if ($c.util.getComponent('dma_submitReq').get('beforeName')!== '') {
        self.before.innerHTML = $c.util.getComponent('dma_submitReq').get('beforeName');
    }
    if (($c.util.getComponent('rd_gubun').getValue() === '0')) {
        var id = $c.util.getComponent("item");
        $c.util.getComponent('ipt_comCode').readOnly = true;
        id.setDisabled(true);
    }
    if (($c.util.getComponent('rd_cnt').getValue() === '0') || ($c.util.getComponent('rd_cnt').getValue() === '1')) {
        var id = $c.util.getComponent("id_img");
        id.innerHTML = "<img src='/img/person/person_search_ti07.gif'/>";
    } else {
        var id = $c.util.getComponent("id_img");
        id.innerHTML = "<img src='/img/person/person_search_ti08.gif'/>";
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.initField
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.initField = function () {
    /* sdd-asis-lifecycle:begin initField — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const f = (document.form || { elements: [] });
    f.name.value = "";
    f.birthday.value = "";
    /* sdd-asis-lifecycle:end */
};


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf30661.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

