        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin rd_gubun_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.itemSelect($c.util.getComponent("rd_gubun"))
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30661.rd_gubun_onclick' }); }
};

