};scwin.ipt_stockRate1_onkeypress = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_stockRate1_onkeypress — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if ($c.util.getKeyCode(event) < 48 || $c.util.getKeyCode(event) > 57){event.returnValue = false;}
