///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_submit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_submit = async function () {
    const sbmOptions = {
        id: "tx_submit",
        method: "post",
        action: "/PersonInfo.do",
        ref: "dma_submitReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf30661.tx_submit" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.submit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.submit = async function () {
    /* sdd-asis-lifecycle:begin submit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const f = (document.form || { elements: [] });
    if (($c.util.getComponent('rd_gubun').getValue() === '1') && ($c.util.getComponent('ipt_comCode').getValue() == null ? '' : String($c.util.getComponent('ipt_comCode').getValue())) === '') {
        await $c.win.alert("종목코드를 입력하셔야 합니다.");
        return;
    }
    f.action = "/PersonInfo.do";
    $c.util.getComponent('dma_submitReq').set('method', "statisticsSearchList");
    $c.util.getComponent("ipt_comName").setValue(encodeURI($c.util.getComponent('ipt_comName').getValue()));
    $c.util.getComponent('dma_submitReq').set('beforeName', encodeURI($c.util.getComponent('dma_submitReq').get('beforeName')));
    if ($c.num.isNumber($c.util.getComponent('ipt_comCode').getValue()) && $c.util.getComponent('ipt_comCode').getValue().length == 6) {
        $c.util.getComponent("ipt_comCode").setValue("A" + $c.util.getComponent('ipt_comCode').getValue());
    }
    if ((document.form || { elements: [] }).regcncl[1].checked) {
        /* 수동 전환 필요: regcncl[0].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
    } else {
        /* 수동 전환 필요: regcncl[0].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
    }
    await scwin.tx_submit();

    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.itemSelect
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.itemSelect = function (obj) {
    /* sdd-asis-lifecycle:begin itemSelect — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const f = (document.form || { elements: [] });
    const id = $c.util.getComponent("item");
    if (obj.getValue() === '0') {
        $c.util.getComponent("ipt_comCode").setValue("");
        $c.util.getComponent("ipt_comName").setValue("");
        $c.util.getComponent('ipt_comCode').readOnly = true;
        id.setDisabled(true);
    } else {
        $c.util.getComponent('ipt_comCode').readOnly = false;
        id.setDisabled(false);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.imgChange
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.imgChange = function (obj) {
    /* sdd-asis-lifecycle:begin imgChange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const id = $c.util.getComponent("id_img");
    if (obj.getValue() === '0' || obj.getValue() === '1') {
        id.innerHTML = "<img src='/img/person/person_search_ti07.gif'/>";
    } else {
        id.innerHTML = "<img src='/img/person/person_search_ti08.gif'/>";
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.clickItem
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.clickItem = async function () {
    /* sdd-asis-lifecycle:begin clickItem — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (($c.util.getComponent('rd_gubun').getValue() === '0')) {
        await $c.win.alert("구분에 종목을 선택해 주세요.");
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchCode
 * @author Inswave
 * @date 2026. 09. 29
 * @param searchValue
 * @returns
 * @hidden N
*/
scwin.searchCode = function (searchValue) {
    /* sdd-asis-lifecycle:begin searchCode — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let iCount = 0;
    arrReset();
    for (let j = 0; j < jr.length; j++) {
        if (searchValue === jr[j].jcode.substring(0, searchValue.length)) {
            if (jr[j].jname.indexOf("변경전사명") < 1) {
                if (regcncl === "1") {
                    arrCode[iCount] = jr[j].jcode;
                    arrName[iCount] = jr[j].jname;
                    iCount++;
                } else {
                    if (jr[j].jname.indexOf("폐지") < 1) {
                        arrCode[iCount] = jr[j].jcode;
                        arrName[iCount] = jr[j].jname;
                        iCount++;
                    }
                }
            }
        }
    }
    setSelectBox();
    /* sdd-asis-lifecycle:end */
};
